// The reTerminal Sticky's own layout: the scene on the whole glass, and a home
// screen around the scene list with the time, the battery and what each key
// beside the glass does, drawn next to that key. Swipe up from the bottom for
// the scene list, down from the top for the settings, in from a side for the
// scene's back and forward (the frame's event map). Two other looks: a rail of
// buttons beside the keys, and a status bar.
const INK = '#000000'
const GREY = '#555555'
const PALE = '#aaaaaa'
const PAPER = '#ffffff'

const pad = (n) => String(n).padStart(2, '0')
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October',
  'November', 'December']

// The three keys on the Sticky's right edge, held upright: AI, then UP and
// DOWN, each as a share of the glass's height from its top (Seeed's appearance
// drawing). Upright is the panel turned 270 degrees; unturned (800x480) they
// are on its top edge, as far from its left.
const KEYS = [
  { label: 'AI', role: 'primary', at: 0.065 },
  { label: 'UP', role: 'up', at: 0.2 },
  { label: 'DOWN', role: 'down', at: 0.345 },
]
// What the frame's own event map says on a Sticky, for a frame that has none
// to tell (the preview): fos_board.c's STICKY_KEYS and the edge swipes.
const STICKY_MAP = [
  { event: 'button', match: { label: 'UP', action: 'longPress' }, emit: 'setCurrentScene', as: { direction: 'prev' } },
  { event: 'button', match: { label: 'DOWN', action: 'longPress' }, emit: 'setCurrentScene', as: { direction: 'next' } },
  { event: 'button', match: { label: 'AI', action: 'longPress' }, emit: 'voiceChat', as: {} },
  { event: 'edgeSwipe', match: { edge: 'left' }, emit: 'back', as: {} },
  { event: 'edgeSwipe', match: { edge: 'right' }, emit: 'forward', as: {} },
  { event: 'edgeSwipe', match: { edge: 'bottom' }, emit: 'sceneSwitcher', as: {} },
  { event: 'edgeSwipe', match: { edge: 'top' }, emit: 'sceneSettings', as: {} },
]
// The key the layout itself listens to: a double press of it opens the scene
// list, where the frame's map leaves that free, and a press, where the map
// leaves the press to the scene, draws the picture again.
const LIST_KEY = 'AI'

// Icons, one path each in a 0 0 24 24 box (Material Design Icons).
const ICON = {
  up: 'M7.41,15.41L12,10.83L16.59,15.41L18,14L12,8L6,14L7.41,15.41Z',
  down: 'M7.41,8.58L12,13.17L16.59,8.58L18,10L12,16L6,10L7.41,8.58Z',
  apps: 'M4,4H10V10H4V4M14,4H20V10H14V4M4,14H10V20H4V14M14,14H20V20H14V14Z',
  cog: 'M12,15.5A3.5,3.5 0 0,1 8.5,12A3.5,3.5 0 0,1 12,8.5A3.5,3.5 0 0,1 15.5,12A3.5,3.5 0 0,1 12,15.5M19.43,12.97C19.47,12.65 19.5,12.33 19.5,12C19.5,11.67 19.47,11.34 19.43,11L21.54,9.37C21.73,9.22 21.78,8.95 21.66,8.73L19.66,5.27C19.54,5.05 19.27,4.96 19.05,5.05L16.56,6.05C16.04,5.66 15.5,5.32 14.87,5.07L14.5,2.42C14.46,2.18 14.25,2 14,2H10C9.75,2 9.54,2.18 9.5,2.42L9.13,5.07C8.5,5.32 7.96,5.66 7.44,6.05L4.95,5.05C4.73,4.96 4.46,5.05 4.34,5.27L2.34,8.73C2.21,8.95 2.27,9.22 2.46,9.37L4.57,11C4.53,11.34 4.5,11.67 4.5,12C4.5,12.33 4.53,12.65 4.57,12.97L2.46,14.63C2.27,14.78 2.21,15.05 2.34,15.27L4.34,18.73C4.46,18.95 4.73,19.03 4.95,18.95L7.44,17.94C7.96,18.34 8.5,18.68 9.13,18.93L9.5,21.58C9.54,21.82 9.75,22 10,22H14C14.25,22 14.46,21.82 14.5,21.58L14.87,18.93C15.5,18.67 16.04,18.34 16.56,17.94L19.05,18.95C19.27,19.03 19.54,18.95 19.66,18.73L21.66,15.27C21.78,15.05 21.73,14.78 21.54,14.63L19.43,12.97Z',
  open: 'M12,2A10,10 0 0,0 2,12A10,10 0 0,0 12,22A10,10 0 0,0 22,12A10,10 0 0,0 12,2M10,17V7L16,12L10,17Z',
  refresh: 'M17.65,6.35C16.2,4.9 14.21,4 12,4A8,8 0 0,0 4,12A8,8 0 0,0 12,20C15.73,20 18.84,17.45 19.73,14H17.65C16.83,16.33 14.61,18 12,18A6,6 0 0,1 6,12A6,6 0 0,1 12,6C13.66,6 15.14,6.69 16.22,7.78L13,11H20V4L17.65,6.35Z',
  swipe: 'M12,2L8,6H11V18H8L12,22L16,18H13V6H16L12,2Z',
}

const Icon = ({ d, size }) => (
  <svg viewBox="0 0 24 24" width={size} height={size}>
    <path d={d} fill="currentColor" />
  </svg>
)

// The side of the picture the keys are on, by the frame's rotation, and how
// far along it the first is: unturned the top edge, turned 270 (upright) the
// right. A picture whose shape the rotation does not explain (the preview of a
// portrait frame) is taken as upright. The owner's "Keys" setting wins.
function keySide(frame, setting) {
  if (['right', 'left', 'top', 'bottom'].includes(setting)) return setting
  const rotate = ((Number(frame.rotate) || 0) % 360 + 360) % 360
  const portrait = frame.height > frame.width
  if (portrait && (rotate === 0 || rotate === 180)) return 'right'
  return { 0: 'top', 90: 'left', 180: 'bottom', 270: 'right' }[rotate] || 'right'
}
// Along a side, as a share of its length: the key order runs down the right
// edge and the top edge, and back up the left and the bottom.
const along = (side, at) => (side === 'right' || side === 'top' ? at : 1 - at)

// What the frame's event map makes of a key, in a word. Under an arrow that
// already says which way, a scene change is just "Scene".
function said(rule) {
  switch (rule.emit) {
    case 'setCurrentScene': return 'Scene'
    case 'voiceChat': return 'Talk'
    case 'sceneSwitcher': return 'Scenes'
    case 'sceneSettings': return 'Settings'
    case 'toggleScreen': return 'Screen'
    case 'render': return 'Refresh'
    case 'back': return 'Back'
    case 'forward': return 'Forward'
    default: return rule.emit ? String(rule.emit) : null
  }
}
function keyRule(map, label, action) {
  return map.find((rule) => rule.event === 'button' && rule.match && rule.match.label === label &&
    (rule.match.action || 'press') === action)
}
const swipeRule = (map, edge) => map.find((rule) => rule.event === 'edgeSwipe' && rule.match && rule.match.edge === edge)
const eventMap = (frame) => (Array.isArray(frame.eventMap) ? frame.eventMap : STICKY_MAP)

// The scene list is showing (built in, its id `system/sceneSwitcher`).
const listShows = (frame) => frame.systemScene === true && String(frame.sceneId || '').startsWith('system/sceneSwitcher')

export function onEvent(app, context) {
  const press = context.payload || {}
  if (context.event !== 'button' || press.label !== LIST_KEY || app.frame.systemScene) return false
  // A press the frame's map binds never reaches the layout: this one is free.
  if ((press.action || 'press') === 'press') frameos.dispatch('render')
  if (press.action === 'doublePress' && !keyRule(eventMap(app.frame), LIST_KEY, 'doublePress')) {
    frameos.dispatch('sceneSwitcher')
  }
  return false
}

// Four bars for the Wi-Fi signal, nothing on a frame that cannot tell.
function Signal({ rssi, u, color }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  return (
    <div className={`flex items-end gap-[${Math.max(1, Math.round(u * 0.4))}px] h-[${Math.round(u * 3)}px]`}>
      {[0.3, 0.55, 0.8, 1].map((share, i) => (
        <div className={`w-[${Math.max(2, Math.round(u * 0.6))}px] h-[${Math.round(u * 3 * share)}px] ${i < level ? `bg-[${color}]` : `bg-[${PALE}]`}`} />
      ))}
    </div>
  )
}

function Battery({ percent, u, color }) {
  if (typeof percent !== 'number') return null
  const w = Math.round(u * 5)
  const h = Math.round(u * 2.6)
  const line = Math.max(1, Math.round(u * 0.3))
  const inner = Math.max(0, Math.round((w - 4 * line) * Math.min(100, Math.max(0, percent)) / 100))
  return (
    <div className="flex items-center gap-[3px]">
      <div className={`flex items-center w-[${w}px] h-[${h}px] p-[${line}px] border-[${line}px] border-[${color}] rounded-[${line * 2}px]`}>
        <div className={`h-full w-[${inner}px] bg-[${color}]`} />
      </div>
      <div className={`w-[${line * 2}px] h-[${Math.round(h / 2.5)}px] bg-[${color}]`} />
      <span className={`pl-[${line * 2}px] text-[${Math.round(u * 3)}px] font-semibold`}>{`${percent}%`}</span>
    </div>
  )
}

// A key's tab at the edge of the glass, beside the key: what a press does, and
// under it, smaller, what holding it does. A tap on the tab is a press of the key.
function KeyTab({ side, u, icon, word, held, lit, tap }) {
  const corner = { right: 'rounded-l-[12px]', left: 'rounded-r-[12px]', top: 'rounded-b-[12px]', bottom: 'rounded-t-[12px]' }[side]
  const look = lit ? `bg-[${INK}] text-[${PAPER}]` : `bg-[${PAPER}] text-[${INK}] border-2 border-[${INK}]`
  // Beside the keys on a side, the icon over the words; along the top or the
  // bottom, where the strip is shallow, beside them.
  const across = side === 'left' || side === 'right'
  const words = (
    <div className={`flex flex-col ${across ? 'items-center' : 'items-start'} gap-[${Math.round(u * 0.4)}px]`}>
      <span className={`text-[${Math.round(u * 3)}px] font-bold leading-none whitespace-nowrap`}>{word}</span>
      {held ? <span className={`text-[${Math.round(u * 2.1)}px] font-semibold leading-none whitespace-nowrap text-[${lit ? PALE : GREY}]`}>{held}</span> : null}
    </div>
  )
  return (
    <div
      className={`flex ${across ? 'flex-col' : 'flex-row'} items-center justify-center gap-[${Math.round(u * 0.6)}px] ${corner} ${look} ${tap ? `active:bg-[${GREY}]` : ''} w-full h-full`}
      onClick={tap}
    >
      <div className="flex shrink-0">
        <Icon d={icon} size={Math.round(u * 3.8)} />
      </div>
      {words}
    </div>
  )
}

// The keys' tabs, each centred on its key along `side`, `length` long, `span`
// along it.
function keyTabs(side, length, span, u, tabs) {
  const across = side === 'left' || side === 'right'
  return tabs.map((tab) => {
    const centre = Math.round(along(side, tab.at) * length)
    const start = Math.max(0, Math.min(length - span, centre - Math.round(span / 2)))
    const place = across ? `top-[${start}px] left-0 w-full h-[${span}px]` : `left-[${start}px] top-0 h-full w-[${span}px]`
    return (
      <div className={`absolute ${place} p-[3px]`}>
        <KeyTab side={side} u={u} icon={tab.icon} word={tab.word} held={tab.held} lit={tab.lit} tap={tab.tap} />
      </div>
    )
  })
}

// Each key's tab: what a press does (the frame's map, else the scene's own:
// UP and DOWN go to it, AI draws it again) and what holding it does. Over the
// scene list a press moves and opens, and UP and DOWN held turn its pages.
function tabsFor(frame, onList) {
  const map = eventMap(frame)
  return KEYS.map((key) => {
    const arrow = key.label === 'UP' ? ICON.up : ICON.down
    const held = keyRule(map, key.label, 'longPress')
    if (onList) {
      const holds = key.label === 'AI' ? (held && held.emit === 'voiceChat' ? 'hold Talk' : null) : held ? 'hold Page' : null
      const word = key.label === 'AI' ? 'Open' : key.label === 'UP' ? 'Up' : 'Down'
      return { at: key.at, icon: key.label === 'AI' ? ICON.open : arrow, word, held: holds, lit: key.label === 'AI' }
    }
    const pressed = keyRule(map, key.label, 'press')
    const word = pressed ? said(pressed) : key.label === 'AI' ? 'Refresh' : key.label === 'UP' ? 'Up' : 'Down'
    const holds = held ? `hold ${said(held)}` : key.label === LIST_KEY && !keyRule(map, LIST_KEY, 'doublePress') ? '2×: Scenes' : null
    const tap = () => frameos.dispatch('button', { label: key.label, role: key.role, action: 'press' })
    return { at: key.at, icon: key.label === 'AI' ? ICON.refresh : arrow, word, held: holds, tap }
  })
}

function clock(now) {
  return `${pad(now.getHours())}:${pad(now.getMinutes())}`
}

// The scene list, as a home screen: the time and the date over it, the
// battery and the signal, the swipes under it, and the keys' tabs beside them.
function Home({ app, side, W, H, u }) {
  const now = new Date()
  const across = side === 'left' || side === 'right'
  const rail = Math.round(u * (across ? 15 : 10))
  const span = Math.round(u * (across ? 13.5 : 20))
  const map = eventMap(app.frame)
  const swipes = []
  if (swipeRule(map, 'bottom')) swipes.push('Swipe up: close')
  if (swipeRule(map, 'top')) swipes.push('down: settings')
  if (swipeRule(map, 'left') || swipeRule(map, 'right')) swipes.push('sideways: pages')
  // How to come back here with the keys, where the frame's map leaves it free.
  const listKeyNote = keyRule(map, LIST_KEY, 'doublePress') ? null : 'Press AI twice on any scene for this list'

  const main = (
    <div className={`flex flex-col flex-1 min-w-0 min-h-0 bg-[${PAPER}] text-[${INK}]`}>
      <div className={`flex items-end px-[${Math.round(u * 4)}px] pt-[${Math.round(u * 3)}px] pb-[${Math.round(u * 1.5)}px] gap-[${Math.round(u * 2)}px]`}>
        <div className="flex flex-col flex-1 min-w-0">
          <span className={`text-[${Math.round(u * 13)}px] font-bold leading-none`}>{clock(now)}</span>
          <span className={`text-[${Math.round(u * 3.6)}px] text-[${GREY}] font-semibold truncate pt-[${Math.round(u)}px]`}>
            {`${DAYS[now.getDay()]}, ${now.getDate()} ${MONTHS[now.getMonth()]}`}
          </span>
        </div>
        <div className={`flex flex-col items-end gap-[${Math.round(u * 1.5)}px] pb-[${Math.round(u * 0.5)}px]`}>
          <Battery percent={app.frame.batteryPercent} u={u} color={INK} />
          <Signal rssi={app.frame.wifiRssi} u={u} color={INK} />
        </div>
      </div>
      <div className={`flex flex-col flex-1 min-h-0 border-t-2 border-[${INK}]`}>
        <yield />
      </div>
      {listKeyNote ? (
        <div className={`flex items-center justify-center h-[${Math.round(u * 5)}px] border-t-2 border-[${INK}] text-[${Math.round(u * 2.9)}px] font-semibold`}>
          <span className="truncate">{listKeyNote}</span>
        </div>
      ) : null}
      {swipes.length ? (
        <div className={`flex items-center justify-center gap-[${Math.round(u * 1.5)}px] h-[${Math.round(u * 5)}px] border-t-2 border-[${INK}] text-[${Math.round(u * 2.9)}px] text-[${GREY}] font-semibold`}>
          <Icon d={ICON.swipe} size={Math.round(u * 3.6)} />
          <span className="truncate">{swipes.join(' · ')}</span>
        </div>
      ) : null}
    </div>
  )
  const keys = (
    <div className={`relative shrink-0 ${across ? `w-[${rail}px] h-full` : `h-[${rail}px] w-full`} bg-[${PAPER}] ${{ right: 'border-l-2', left: 'border-r-2', top: 'border-b-2', bottom: 'border-t-2' }[side]} border-[${INK}]`}>
      {keyTabs(side, across ? H : W, span, u, tabsFor(app.frame, true))}
    </div>
  )
  const first = side === 'left' || side === 'top'
  return (
    <div className={`flex ${across ? 'flex-row' : 'flex-col'} w-full h-full bg-[${PAPER}]`}>
      {first ? keys : null}
      {main}
      {first ? null : keys}
    </div>
  )
}

// The rail: a strip along the keys' side with their tabs, the scene list and
// the settings under them, and the battery and the time at its end.
function Rail({ app, side, W, H, u }) {
  const across = side === 'left' || side === 'right'
  const rail = Math.round(u * (across ? 15 : 10))
  const span = Math.round(u * (across ? 13.5 : 20))
  const button = Math.round(u * (across ? 12 : 7.5))
  const now = new Date()
  // Square with the word under the icon on a side; along the top or the
  // bottom, as shallow as the strip allows, the word beside it.
  const Button = ({ icon, word, tap }) => (
    <div
      className={`flex ${across ? `flex-col w-[${button}px]` : `flex-row gap-[${Math.round(u)}px] px-[${Math.round(u * 2)}px]`} items-center justify-center h-[${button}px] rounded-[12px] border-2 border-[${INK}] active:bg-[${GREY}] active:text-[${PAPER}]`}
      onClick={tap}
    >
      <Icon d={icon} size={Math.round(u * (across ? 5.4 : 4))} />
      <span className={`text-[${Math.round(u * (across ? 2.2 : 3))}px] font-bold leading-none`}>{word}</span>
    </div>
  )
  const status = (
    <div className={`flex ${across ? 'flex-col' : 'flex-row'} items-center gap-[${Math.round(u)}px] text-[${Math.round(u * 3.4)}px] font-bold`}
      onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })}>
      <span>{clock(now)}</span>
      <Signal rssi={app.frame.wifiRssi} u={u * 0.8} color={INK} />
      {typeof app.frame.batteryPercent === 'number' ? <span className={`text-[${Math.round(u * 2.8)}px]`}>{`${app.frame.batteryPercent}%`}</span> : null}
    </div>
  )
  const strip = (
    <div className={`relative flex ${across ? 'flex-col' : 'flex-row'} items-center justify-end shrink-0 gap-[${Math.round(u * 2)}px] ${across ? `w-[${rail}px] h-full pb-[${Math.round(u * 3)}px]` : `h-[${rail}px] w-full pr-[${Math.round(u * 3)}px]`} bg-[${PAPER}] text-[${INK}] ${{ right: 'border-l-2', left: 'border-r-2', top: 'border-b-2', bottom: 'border-t-2' }[side]} border-[${INK}]`}>
      {keyTabs(side, across ? H : W, span, u, tabsFor(app.frame, false))}
      <Button icon={ICON.apps} word="Scenes" tap={() => frameos.dispatch('sceneSwitcher')} />
      <Button icon={ICON.cog} word="Settings" tap={() => frameos.dispatch('sceneSettings')} />
      {status}
    </div>
  )
  const first = side === 'left' || side === 'top'
  return (
    <div className={`flex ${across ? 'flex-row' : 'flex-col'} w-full h-full bg-[${PAPER}]`}>
      {first ? strip : null}
      <div className="flex flex-col flex-1 min-w-0 min-h-0">
        <yield />
      </div>
      {first ? null : strip}
    </div>
  )
}

// The status bar: the time, the scene's name (a tap: the scene list) and the
// signal and the battery (a tap: the frame's page), over the scene.
function Bar({ app, u }) {
  const now = new Date()
  return (
    <div className={`flex flex-col w-full h-full bg-[${PAPER}] text-[${INK}]`}>
      <div className={`flex items-center h-[${Math.round(u * 7)}px] px-[${Math.round(u * 3)}px] gap-[${Math.round(u * 2)}px] border-b-2 border-[${INK}] text-[${Math.round(u * 3.4)}px] font-bold`}>
        <span>{clock(now)}</span>
        <div className="flex flex-1 items-center justify-center min-w-0 h-full gap-[4px]" onClick={() => frameos.dispatch('sceneSwitcher')}>
          <Icon d={ICON.apps} size={Math.round(u * 3.4)} />
          <span className="truncate">{app.frame.sceneName || 'Scenes'}</span>
        </div>
        <div className={`flex items-center h-full gap-[${Math.round(u * 2)}px]`} onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })}>
          <Signal rssi={app.frame.wifiRssi} u={u} color={INK} />
          <Battery percent={app.frame.batteryPercent} u={u} color={INK} />
        </div>
      </div>
      <div className="flex flex-col flex-1 min-h-0">
        <yield />
      </div>
    </div>
  )
}

export function get(app) {
  const frame = app.frame
  const W = frame.width
  const H = frame.height
  // One unit, a hundredth of the shorter edge: the same look either way round.
  const u = Math.min(W, H) / 100
  const side = keySide(frame, app.state.keys)
  if (listShows(frame) && app.state.home !== 'false' && app.state.home !== false) {
    return <Home app={app} side={side} W={W} H={H} u={u} />
  }
  // The settings get the whole glass: they have a keyboard to show.
  if (frame.systemScene) return <yield />
  if (app.state.look === 'rail') return <Rail app={app} side={side} W={W} H={H} u={u} />
  if (app.state.look === 'bar') return <Bar app={app} u={u} />
  return <yield />
}
